package com.fasterxml.jackson.core.io;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for com.fasterxml.jackson.core.io.NumberInput.parseLong(String)
 */
public class NumberInput_parseLong_TriageGen1Test {

    @Test
    public void testParseLong_ShortString_UsesIntParsing() {
        // length <= 9 case: "123" (len 3)
        assertEquals(123L, NumberInput.parseLong("123"));
        // length <= 9 case: "2147483647" (len 10 is actually limit, but let's check 9)
        // "123456789" is length 9
        assertEquals(123456789L, NumberInput.parseLong("123456789"));
    }

    @Test
    public void testParseLong_LongString_UsesLongParsing() {
        // length > 9 case: "1000000000" (len 10)
        assertEquals(1000000000L, NumberInput.parseLong("1000000000"));
        // Large long
        assertEquals(9223372036854775807L, NumberInput.parseLong("9223372036854775807"));
    }

    @Test
    public void testParseLong_NegativeShortString() {
        // length <= 9 case: "-123" (len 4)
        assertEquals(-123L, NumberInput.parseLong("-123"));
    }

    @Test
    public void testParseLong_NegativeLongString() {
        // length > 9 case: "-1000000000" (len 11)
        assertEquals(-1000000000L, NumberInput.parseLong("-1000000000"));
    }

    @Test(expected = NumberFormatException.class)
    public void testParseLong_InvalidFormat_ThrowsException() {
        NumberInput.parseLong("abc");
    }

    @Test(expected = NumberFormatException.class)
    public void testParseLong_EmptyString_ThrowsException() {
        NumberInput.parseLong("");
    }

    @Test(expected = NumberFormatException.class)
    public void testParseLong_TooLargeForLong_ThrowsException() {
        // Exceeds Long.MAX_VALUE
        NumberInput.parseLong("9223372036854775808");
    }

    @Test(expected = NumberFormatException.class)
    public void testParseLong_InvalidIntRange_ThrowsException() {
        // This tests the branch where length <= 9 but parseInt fails
        // However, max int is 2147483647 (10 digits). 
        // A 9 digit number will always pass parseInt.
        // Let's try a 10 digit number that is too large for int but small for long
        // to ensure it hits the Long.parseLong branch.
        // "2147483648" is length 10.
        assertEquals(2147483648L, NumberInput.parseLong("2147483648"));
    }

    @Test
    public void testParseLong_BoundaryInt() {
        // Max int is 2147483647 (10 digits). 
        // To trigger the "length <= 9" branch specifically:
        assertEquals(999999999L, NumberInput.parseLong("999999999"));

        // To trigger the "length > 9" branch:
        assertEquals(2147483647L, NumberInput.parseLong("2147483647"));
    }
}
